lause","Property claim valuation","Hail damage","Ice dams","Snow load","Xactimate estimating"],"priceRange":"$$","openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://northdakotainsuranceappraiser.com/#website","url":"https://northdakotainsuranceappraiser.com/","name":"North Dakota Insurance Appraiser","publisher":{"@id":"https://northdakotainsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://northdakotainsuranceappraiser.com/appraisal-terms-a-z/#webpage","url":"https://northdakotainsuranceappraiser.com/appraisal-terms-a-z/","name":"Insurance Appraisal Glossary | ACV, Umpire & More","description":"Plain-English definitions of property claim terms: actual cash value, replacement cost, ice dam, snow load, appraisal award, umpire, O&P and more.","inLanguage":"en-US","isPartOf":{"@id":"https://northdakotainsuranceappraiser.com/#website"},"about":{"@id":"https://northdakotainsuranceappraiser.com/#business"},"publisher":{"@id":"https://northdakotainsuranceappraiser.com/#business"},"dateModified":"2026-11-13","primaryImageOfPage":{"@type":"ImageObject","@id":"https://northdakotainsuranceappraiser.com/appraisal-terms-a-z/#primaryimage","url":"https://northdakotainsuranceappraiser.com/assets/img/photos/laptop-work.webp","width":1200,"height":800},"breadcrumb":{"@id":"https://northdakotainsuranceappraiser.com/appraisal-terms-a-z/#breadcrumb"},"mainEntity":{"@id":"https://northdakotainsuranceappraiser.com/appraisal-terms-a-z/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://northdakotainsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Appraisal terms A–Z","item":"https://northdakotainsuranceappraiser.com/appraisal-terms-a-z/"}],"@id":"https://northdakotainsuranceappraiser.com/appraisal-terms-a-z/#breadcrumb"},{"@type":"DefinedTermSet","name":"Insurance appraisal terms A–Z","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value","description":"The value of damaged property at the time of loss, usually calculated as replacement cost minus depreciation. Many policies pay this amount first."},{"@type":"DefinedTerm","name":"Additional living expense","description":"Coverage for the extra costs of living elsewhere, such as lodging and meals above normal, while a home is unlivable after a covered loss. Often part of Coverage D."},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision that sets the amount of loss, signed by any two of the three panel members: the two appraisers and the umpire."},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy provision that lets either side demand appraisal when they disagree on the amount of a covered loss."},{"@type":"DefinedTerm","name":"Appraisal demand","description":"A written notice from the policyholder or insurer invoking the appraisal clause and starting the process."},{"@type":"DefinedTerm","name":"Claim number","description":"The identifier an insurer assigns to a reported loss. It belongs on every letter, estimate, and invoice tied to the claim."},{"@type":"DefinedTerm","name":"Coverage A","description":"The dwelling coverage on a homeowners policy, which pays for damage to the house and attached structures."},{"@type":"DefinedTerm","name":"Coverage B","description":"Other structures coverage, for detached garages, sheds, fences, and similar buildings on the property."},{"@type":"DefinedTerm","name":"Coverage C","description":"Personal property coverage, for belongings such as furniture, clothing, and electronics."},{"@type":"DefinedTerm","name":"Coverage D","description":"Loss of use coverage, which typically pays additional living expense or lost rental income after a covered loss."},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of a policy listing the insured, property, coverages, limits, deductibles, and policy period."},{"@type":"DefinedTerm","name":"Deductible","description":"The portion of a covered loss the policyholder pays before the insurer pays. It may be a flat amount or a percentage."},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value for age, wear, and condition. Insurers subtract it to reach actual cash value."},{"@type":"DefinedTerm","name":"Derecho","description":"A long-lived, widespread windstorm produced by a line of fast-moving thunderstorms, capable of damage across many counties."},{"@type":"DefinedTerm","name":"Disinterested appraiser","description":"An appraiser with no financial or personal stake in the outcome beyond a reasonable fee, as most appraisal clauses require."},{"@type":"DefinedTerm","name":"Drip edge","description":"Metal flashing installed along roof eaves and rakes to direct water into gutters and away from the fascia and decking."},{"@type":"DefinedTerm","name":"Estimate","description":"An itemized statement of the work and materials needed to repair a loss, with quantities and prices for each line."},{"@type":"DefinedTerm","name":"Exclusion","description":"A policy provision that removes certain causes of loss or types of property from coverage, such as flood on a standard homeowners policy."},{"@type":"DefinedTerm","name":"Hail strike","description":"A point of impact from a hailstone, often seen as a bruise, fracture, or loss of granules on shingles or a dent in metal."},{"@type":"DefinedTerm","name":"Ice and water shield","description":"A self-adhering waterproof membrane installed under shingles at eaves, valleys, and penetrations to resist ice dams and wind-driven rain."},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice that forms at a roof edge when melting snow refreezes, backing water up under shingles and into the home."},{"@type":"DefinedTerm","name":"Line item","description":"A single entry in an estimate describing one task or material, with a quantity, unit, and price."},{"@type":"DefinedTerm","name":"Matching","description":"The question of whether undamaged materials must be replaced so repairs reasonably match the rest of the surface in color, texture, or style."},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps taken after a loss to prevent further damage, such as tarping a roof or drying out a wet basement."},{"@type":"DefinedTerm","name":"NFIP","description":"The National Flood Insurance Program, the federal program that writes most flood insurance policies in the United States."},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for added costs to bring repaired or rebuilt property up to current building codes."},{"@type":"DefinedTerm","name":"Overhead and profit","description":"A general contractor’s charges for business overhead and profit, often 10% each in estimates, when a loss requires coordination of multiple trades."},{"@type":"DefinedTerm","name":"Percentage deductible","description":"A deductible calculated as a percentage of the dwelling limit rather than a flat dollar amount, common for wind and hail on some policies."},{"@type":"DefinedTerm","name":"Pitch","description":"The steepness of a roof, expressed as rise over 12 inches of run. Steeper roofs usually cost more to repair."},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, which some policies require within a set time after the insurer asks for it."},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation withheld from an initial payment that the insurer pays later, usually once repairs are completed under a replacement cost policy."},{"@type":"DefinedTerm","name":"Replacement cost value","description":"The cost to repair or replace damaged property with materials of like kind and quality, without subtracting depreciation."},{"@type":"DefinedTerm","name":"Reservation of rights","description":"A letter in which the insurer continues handling a claim while reserving the right to deny coverage later."},{"@type":"DefinedTerm","name":"Scope of loss","description":"The description of all damage and the work needed to repair it. Many disputes come down to differences in scope."},{"@type":"DefinedTerm","name":"Snow load","description":"The weight of accumulated snow and ice on a roof. Heavy loads can crack trusses or collapse structures."},{"@type":"DefinedTerm","name":"Square (roofing)","description":"A unit of roofing measure equal to 100 square feet of roof surface."},{"@type":"DefinedTerm","name":"Subrogation","description":"The insurer’s right, after paying a claim, to recover its payment from a third party who caused the loss."},{"@type":"DefinedTerm","name":"Suit limitation","description":"A policy provision, together with state law, that limits how long a policyholder has to file a lawsuit over a claim."},{"@type":"DefinedTerm","name":"Supplement","description":"A request for additional payment for damage or costs found after the original estimate, often during repairs."},{"@type":"DefinedTerm","name":"Surplus lines","description":"Insurance written by carriers not licensed as standard insurers in the state, often used for hard-to-place risks."},{"@type":"DefinedTerm","name":"Tear-off","description":"Removal of existing roofing layers down to the decking before new roofing is installed."},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the two appraisers cannot agree on."},{"@type":"DefinedTerm","name":"Waste factor","description":"An added percentage of material in an estimate to account for cutting and fitting, especially for roofing and siding."},{"@type":"DefinedTerm","name":"Xactimate","description":"A widely used estimating software program that insurers and contractors use to price repairs with regional unit costs."}],"@id":"https://northdakotainsuranceappraiser.com/appraisal-terms-a-z/#definedtermset"}]}</script>
</head>
